import React, { useState, useRef, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { FiUser, FiLogOut, FiShoppingBag, FiPlusCircle, FiSearch } from 'react-icons/fi';

const Header = () => {
    const { user, logout } = useAuth();
    const navigate = useNavigate();
    const [searchTerm, setSearchTerm] = useState('');
    const [menuOpen, setMenuOpen] = useState(false);
    const menuRef = useRef(null);
    const buttonRef = useRef(null);

    // Fechar menu ao clicar fora
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (menuRef.current && !menuRef.current.contains(event.target) && 
                buttonRef.current && !buttonRef.current.contains(event.target)) {
                setMenuOpen(false);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, []);

    const handleSearch = (e) => {
        e.preventDefault();
        navigate(`/?search=${encodeURIComponent(searchTerm)}`);
    };

    const toggleMenu = () => {
        setMenuOpen(!menuOpen);
    };

    const closeMenu = () => {
        setMenuOpen(false);
    };

    return (
        <header className="bg-primary-600 text-white shadow-md sticky top-0 z-50">
            <div className="container mx-auto px-4 py-3">
                <div className="flex items-center justify-between flex-wrap gap-3">
                    <Link to="/" className="flex items-center space-x-2">
                        <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center text-primary-600 font-bold text-xl">
                            TM
                        </div>
                        <span className="text-xl font-bold">TechMarket Angola</span>
                    </Link>

                    <form onSubmit={handleSearch} className="flex-1 max-w-md">
                        <div className="relative">
                            <input
                                type="text"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                placeholder="Buscar produtos..."
                                className="w-full px-4 py-2 pl-10 rounded-lg text-gray-900 focus:outline-none"
                            />
                            <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                        </div>
                    </form>

                    <nav className="flex items-center space-x-4">
                        {user ? (
                            <>
                                {user.type === 'vendedor' && (
                                    <Link to="/create-product" className="flex items-center space-x-1 bg-white text-primary-600 px-3 py-2 rounded-lg hover:bg-gray-100">
                                        <FiPlusCircle />
                                        <span className="hidden sm:inline">Anunciar</span>
                                    </Link>
                                )}
                                <Link to={user.type === 'vendedor' ? '/seller/dashboard' : '/buyer/dashboard'} className="hover:text-gray-200">
                                    <FiShoppingBag size={20} />
                                </Link>
                                
                                {/* Menu dropdown com delay */}
                                <div className="relative inline-block">
                                    <button
                                        ref={buttonRef}
                                        onClick={toggleMenu}
                                        onMouseEnter={() => {
                                            const timer = setTimeout(() => setMenuOpen(true), 200);
                                            return () => clearTimeout(timer);
                                        }}
                                        className="flex items-center space-x-2 hover:text-gray-200 transition px-2 py-1 rounded"
                                    >
                                        <span className="text-sm hidden sm:inline">{user.name}</span>
                                    </button>
                                    
                                    {menuOpen && (
                                        <div
                                            ref={menuRef}
                                            onMouseEnter={() => setMenuOpen(true)}
                                            onMouseLeave={() => {
                                                const timer = setTimeout(() => setMenuOpen(false), 300);
                                                return () => clearTimeout(timer);
                                            }}
                                            className="absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-lg py-2 z-50"
                                        >
                                            <Link
                                                to="/profile"
                                                className="flex items-center space-x-2 px-4 py-2 hover:bg-gray-100 text-gray-700 transition"
                                                onClick={closeMenu}
                                            >
                                                <FiUser size={16} />
                                                <span>Meu Perfil</span>
                                            </Link>
                                            <button
                                                onClick={() => {
                                                    logout();
                                                    closeMenu();
                                                }}
                                                className="flex items-center space-x-2 px-4 py-2 hover:bg-gray-100 w-full text-left text-gray-700 transition"
                                            >
                                                <FiLogOut size={16} />
                                                <span>Sair</span>
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </>
                        ) : (
                            <>
                                <Link to="/login" className="flex items-center space-x-1 bg-white text-primary-600 px-4 py-2 rounded-lg">
                                    <FiUser />
                                    <span>Entrar</span>
                                </Link>
                                <Link to="/register" className="flex items-center space-x-1 border border-white px-4 py-2 rounded-lg hover:bg-white hover:text-primary-600">
                                    <span>Cadastrar</span>
                                </Link>
                            </>
                        )}
                    </nav>
                </div>
            </div>
        </header>
    );
};

export default Header;
